def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n < 4:
        return 'C'

    # Count opponent defections in recent window
    def opp_defects(k):
        cnt = 0
        for i in range(n - 1, max(-1, n - k - 1), -1):
            if history[i][1] == 'D':
                cnt += 1
        return cnt

    recent_opp_def = opp_defects(6)
    last_me, last_op = history[-1]

    # Detect sustained defection
    if recent_opp_def >= 5:
        return 'D'

    # If opponent defected last round, retaliate once unless very cooperative
    if last_op == 'D':
        # Check overall cooperation rate
        total_opp_c = 0
        for i in range(n):
            if history[i][1] == 'C':
                total_opp_c += 1
        if total_opp_c * 2 >= n:
            # Mostly cooperative; forgive after one retaliation
            if last_me == 'D':
                return 'C'
            return 'D'
        return 'D'

    # Opponent cooperated last round.
    # If we defected last round, return to cooperation to rebuild trust.
    if last_me == 'D':
        return 'C'

    # Count opponent cooperation overall
    total_opp_c = 0
    for i in range(n):
        if history[i][1] == 'C':
            total_opp_c += 1
    opp_rate = total_opp_c / n

    # Rare probing against very cooperative opponents
    if opp_rate >= 0.85 and recent_opp_def == 0 and n < 95:
        if n % 19 == 0 and rng.random() < 0.12:
            return 'D'
        return 'C'

    # Endgame: if opponent very cooperative, defect near the end
    if n >= 96 and opp_rate >= 0.8:
        return 'D'

    return 'C'
